gamH(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0623\u0645\u0627\u0645 \u0645\u0646\u0637\u0642\u0629 \u062c\u0632\u0627\u0626\u0647. \u0644\u0627 \u062a\u0628\u0642\u0649 \u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647."},
gamI(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062a\u064f\u062a\u0631\u0643 \u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u064a \u0623\u0645\u0627\u0645\u0647 \u0644\u0644\u062e\u0635\u0645."},
